const BEH=[
{who:"Phụ huynh",
 mn:{t:"Mở app nhiều lần mỗi ngày và mong mọi thứ đến qua thông báo đẩy: điểm danh theo thời gian thực kèm lịch sử vào và ra, nhật ký hoạt động hằng ngày, tin nhắn, nhắc học phí và báo cáo phát triển, sức khỏe hằng tháng (DreamKids). Đăng ký người đón, biểu đồ tăng trưởng, dặn thuốc và thực đơn là các phần quen thuộc của app phụ huynh Mầm non.",s:["dreamkids","kids","mega"]},
 k12:{t:"Vào app quanh các kết quả và thời điểm quan trọng. Các app K12 tại Việt Nam đặt điểm số, hạnh kiểm, thi cử và cảnh báo lên đầu, và SISAP gửi thông báo khi có điểm mới, đổi thời khóa biểu, khoản phí mới hoặc sự cố y tế. Giả thuyết cần kiểm chứng bằng dữ liệu ECO Me: phụ huynh K12 vào app theo các thời điểm đó hơn là hằng ngày.",s:["sisap_p","sisap_fpt","vnedu_conn2"]},
 pl:{t:"Mầm non: ưu tiên thông báo đẩy và thao tác nhanh trên điện thoại. K12: điện thoại cho cảnh báo và xem nhanh; xuất file hoặc PDF khi cần giấy tờ (SMAS có web, app và xuất Excel, PDF).",s:["smas_web","fpt_smas"]}},
{who:"Giáo viên",
 mn:{t:"Một hai giáo viên chủ nhiệm ở cùng trẻ cả ngày: ghi nhanh và đều (điểm danh, nhiệt độ, bữa ăn, giấc ngủ, vệ sinh) và duyệt yêu cầu của phụ huynh, trên điện thoại hoặc máy tính bảng. Thêm vào đó là khối sổ sách nặng: kế hoạch theo năm, tháng, tuần, ngày, hồ sơ phát triển, sổ chuyên cần, nhật ký, thường phải làm vừa giấy vừa phần mềm.",s:["sanan_t","tomia_t","gd_net"]},
 k12:{t:"Giáo viên bộ môn dạy nhiều lớp. Điểm được nhập theo từng học sinh và từng cột điểm, hoặc nhập hàng loạt từ mẫu Excel; điện thoại phục vụ nhập điểm nhanh, điểm danh theo tiết và xem lịch báo giảng. Ký học bạ dùng USB token trên máy tính hoặc ký trên điện thoại. Thông tư 29/2024 thêm yêu cầu báo cáo hiệu trưởng.",s:["smas_excel","sisap_t","vnedu_sign","misa_sign","tt29_a"]},
 pl:{t:"Mầm non: ưu tiên thao tác nhanh trong ngày; sổ sách và kế hoạch cần chỗ làm việc dài hơi. K12: cần cả hai; nhập hàng loạt, in và ký bằng USB token nghiêng về máy tính, thao tác đơn lẻ nghiêng về điện thoại."}},
{who:"Nhà trường (quản trị)",
 mn:{t:"Phụ trách thực đơn và dinh dưỡng, khám sức khỏe hai lần mỗi năm và theo dõi tăng trưởng (mỗi tháng với trẻ dưới 24 tháng, mỗi quý sau đó theo thông tư liên tịch cũ), giám sát chăm sóc hằng ngày, thu học phí và tuyển sinh.",s:["vnedu_doc","gd_growth"]},
 k12:{t:"Phụ trách xếp thời khóa biểu, hai chế độ đánh giá (Tiểu học nhận xét và mức, bậc trung học điểm số), thi cử, các sổ có chữ ký số, sổ đăng ký học thêm, thu BHYT và báo cáo tuân thủ; hạn làm sạch dữ liệu 30/10/2026 và trục dữ liệu dùng chung của HCMC làm áp lực tăng lên.",s:["tt27","tt22","tt29_a","bhyt","moet_6020b"]},
 pl:{t:"Ưu tiên web portal cho cả hai nhóm. Điện thoại chỉ dùng để xem nhanh và duyệt; MISA đã có app lãnh đạo trên điện thoại.",s:["misa_lead"]}},
{who:"Học sinh",
 mn:{t:"Không phải người dùng. Trẻ còn nhỏ; phụ huynh và giáo viên thao tác thay."},
 k12:{t:"Có điện thoại riêng: một khảo sát được trích trong nghiên cứu ở Nghệ An cho thấy 100% học sinh THPT được hỏi có điện thoại, dùng trung bình 5,4 giờ mỗi ngày. Học sinh lớp 10 tự chọn tổ hợp môn và tự quản lý bài tập.",s:["hue_phone","combo_a"]},
 pl:{t:"Ưu tiên điện thoại (tối thiểu là web responsive); biểu mẫu dài và bài kiểm tra cần thêm giao diện máy tính."}}
];
